"""Model registry for Copilot v2.

The frontend's model picker offers a small, fixed menu. This module is the
single source of truth for that menu: each :class:`ModelSpec` declares a model's
canonical id, the provider that drives it, and whether it can emit reasoning.
The three public helpers are all lookups against that table:

* :func:`validate_model` — reject a client-supplied id that isn't on the menu.
* :func:`resolve_model` — hand ``Agent`` the right model (OpenAI reasoning
  models must be driven through the Responses API to surface reasoning).
* :func:`build_model_settings` — the per-run provider settings (thinking config,
  max tokens, reasoning effort).

Adding a model is a one-line edit to ``_MODELS``; there are no per-provider
prefix heuristics to keep in sync.
"""

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from typing import Any, cast

from pydantic_ai.models import Model
from pydantic_ai.settings import ModelSettings

from rasa.builder.copilot.pydantic_ai._anthropic_compat import (
    apply_anthropic_compat_shims,
)
from rasa.builder.copilot.pydantic_ai.types import ThinkingPref

apply_anthropic_compat_shims()

# Anthropic requires an explicit max_tokens; this ceiling also bounds thinking.
_ANTHROPIC_MAX_TOKENS = 16384

# Anthropic manual thinking requires ``1024 <= budget_tokens < max_tokens``; a
# budget outside this window is itself a 400, so we clamp client budgets to it.
_MIN_ANTHROPIC_THINKING_BUDGET = 1024
_MAX_ANTHROPIC_THINKING_BUDGET = _ANTHROPIC_MAX_TOKENS - 1

# OpenAI exposes the same models through Chat Completions (``openai`` /
# ``openai-chat``) and the Responses API (``openai-responses``). They all name
# one logical model, so the aliases fold onto a single canonical provider.
_PROVIDER_ALIASES = {
    "openai-chat": "openai",
    "openai-responses": "openai",
}


class Provider(str, Enum):
    """Provider that knows how to drive a model and build its settings."""

    OPENAI = "openai"
    ANTHROPIC = "anthropic"


class ReasoningType(str, Enum):
    """How a model accepts reasoning configuration.

    Reasoning support is not a single boolean: providers (and even models within
    one provider) accept different request shapes, and sending the wrong one is a
    hard 400. This enum is the per-model source of truth that
    :func:`build_model_settings` branches on.

    * ``NONE`` — the model cannot reason; thinking preferences are ignored.
    * ``OPENAI_EFFORT`` — OpenAI reasoning via the Responses API ``reasoning.effort``.
    * ``ANTHROPIC_ADAPTIVE`` — Anthropic adaptive thinking (``{"type": "adaptive"}``)
      tuned by ``output_config.effort`` (Sonnet 4.6 / Opus 4.6+).
    * ``ANTHROPIC_BUDGET`` — Anthropic manual extended thinking
      (``{"type": "enabled", "budget_tokens": N}``); the model self-regulates and
      rejects adaptive/effort (e.g. Claude Haiku 4.5).
    """

    NONE = "none"
    OPENAI_EFFORT = "openai_effort"
    ANTHROPIC_ADAPTIVE = "anthropic_adaptive"
    ANTHROPIC_BUDGET = "anthropic_budget"


@dataclass(frozen=True)
class ModelSpec:
    """One model the frontend may select, and how Copilot v2 drives it.

    ``label`` is the display name the frontend's picker shows for the model.
    ``reasoning_type`` declares which reasoning request shape the model accepts;
    ``supports_reasoning`` is derived from it.
    """

    id: str
    label: str
    provider: Provider
    reasoning_type: ReasoningType

    @property
    def supports_reasoning(self) -> bool:
        """Return whether this model can emit reasoning at all."""
        return self.reasoning_type is not ReasoningType.NONE


# The model picker menu — the single source of truth the frontend fetches via
# :func:`list_models` (``GET /api/copilot/v2/models``), so the menu lives here
# only. ``id`` is the canonical ``<provider>:<model>`` form; client ids are
# normalized to it before lookup.
_MODELS: tuple[ModelSpec, ...] = (
    ModelSpec(
        "openai:gpt-5.4", "GPT-5.4", Provider.OPENAI, ReasoningType.OPENAI_EFFORT
    ),
    ModelSpec(
        "openai:gpt-5.4-mini",
        "GPT-5.4 mini",
        Provider.OPENAI,
        ReasoningType.OPENAI_EFFORT,
    ),
    ModelSpec(
        "anthropic:claude-sonnet-4-6",
        "Claude Sonnet 4.6",
        Provider.ANTHROPIC,
        ReasoningType.ANTHROPIC_ADAPTIVE,
    ),
    # Haiku 4.5 supports reasoning only via manual token budgets; it rejects
    # adaptive thinking and the effort parameter with a 400.
    ModelSpec(
        "anthropic:claude-haiku-4-5",
        "Claude Haiku 4.5",
        Provider.ANTHROPIC,
        ReasoningType.ANTHROPIC_BUDGET,
    ),
)

_BY_ID: dict[str, ModelSpec] = {spec.id: spec for spec in _MODELS}


def _canonical_id(model_id: str) -> str:
    """Fold a provider alias onto its canonical id (``openai-chat:x`` -> ``openai:x``).

    Ids without a provider prefix are returned unchanged.
    """
    provider, sep, name = model_id.partition(":")
    if not sep:
        return model_id
    return f"{_PROVIDER_ALIASES.get(provider, provider)}:{name}"


def _lookup(model_id: str) -> ModelSpec | None:
    """Return the spec for a (possibly aliased) model id, or ``None`` if unknown."""
    return _BY_ID.get(_canonical_id(model_id))


def supports_reasoning(model_id: str) -> bool:
    """Return whether reasoning can be requested for the given model."""
    spec = _lookup(model_id)
    return spec is not None and spec.supports_reasoning


def list_models(default_model_id: str | None = None) -> list[dict[str, Any]]:
    """Return the model-picker menu as JSON-serializable dicts, in menu order.

    This is what ``GET /api/copilot/v2/models`` serves so the frontend renders
    its picker from the backend registry instead of a hardcoded copy. Keys are
    camelCase to match the AG-UI wire vocabulary the rest of Copilot v2 emits.

    ``default_model_id`` is the server's configured default (typically
    ``PydanticAIConfig.model_name``); it is canonicalized before comparison so a
    provider-aliased default (e.g. ``openai-chat:gpt-5.4``) still flags the right
    entry. When it is ``None`` or off-menu, no entry is marked as default.
    """
    default_id = _canonical_id(default_model_id) if default_model_id else None
    return [
        {
            "id": spec.id,
            "label": spec.label,
            "provider": spec.provider.value,
            "supportsReasoning": spec.supports_reasoning,
            "default": spec.id == default_id,
        }
        for spec in _MODELS
    ]


def validate_model(model_id: str) -> str:
    """Return ``model_id`` if it is on the menu, else raise ``ValueError``.

    Guards the client-supplied id at the request boundary so an untrusted request
    can only pick a vetted model, not an arbitrary one.
    """
    if _lookup(model_id) is None:
        allowed = ", ".join(sorted(_BY_ID))
        raise ValueError(f"Unsupported model '{model_id}'. Allowed models: {allowed}.")
    return model_id


def resolve_model(model_id: str, thinking: ThinkingPref) -> Model | str:
    """Return what ``Agent`` should run for this id.

    OpenAI reasoning models must be driven through the Responses API: the default
    resolution uses Chat Completions, which never surfaces reasoning tokens.
    Everything else passes through unchanged as the original id string.
    """
    spec = _lookup(model_id)
    if (
        thinking.enabled
        and spec is not None
        and spec.provider is Provider.OPENAI
        and spec.supports_reasoning
        and not model_id.startswith("openai-responses:")
    ):
        # Lazy import keeps the OpenAI Responses dependency optional.
        from pydantic_ai.models.openai import OpenAIResponsesModel
        from pydantic_ai.providers.openai import OpenAIProvider

        _, _, name = _canonical_id(model_id).partition(":")
        return OpenAIResponsesModel(name, provider=OpenAIProvider())
    return model_id


def build_model_settings(model_id: str, thinking: ThinkingPref) -> ModelSettings | None:
    """Build the provider-specific model settings for one run.

    Dispatches on the model's :class:`ReasoningType` so each model gets only the
    request shape it accepts:

    * Anthropic: always sets ``max_tokens``; when reasoning is on, adds adaptive
      thinking + effort (``ANTHROPIC_ADAPTIVE``) or a manual ``budget_tokens``
      (``ANTHROPIC_BUDGET``) — never both, since Haiku 4.5 rejects adaptive/effort.
    * OpenAI reasoning models with reasoning on: sets the Responses reasoning
      effort and asks for a detailed summary.
    * Anything else: no settings.
    """
    spec = _lookup(model_id)
    if spec is None:
        return None

    if spec.provider is Provider.ANTHROPIC:
        return _anthropic_settings(spec, thinking)

    if spec.reasoning_type is ReasoningType.OPENAI_EFFORT and thinking.enabled:
        from pydantic_ai.models.openai import OpenAIResponsesModelSettings

        return OpenAIResponsesModelSettings(
            openai_reasoning_effort=thinking.effort.value,
            openai_reasoning_summary="detailed",
            openai_send_reasoning_ids=True,
        )

    return None


def _anthropic_settings(spec: ModelSpec, thinking: ThinkingPref) -> ModelSettings:
    """Build Anthropic model settings, choosing the thinking shape by model.

    ``max_tokens`` is always set (Anthropic requires it). When thinking is on,
    the thinking block matches the model's ``reasoning_type``: adaptive+effort or
    a clamped manual ``budget_tokens``.
    """
    # ModelSettings is a TypedDict; keys are dynamic, so cast rather than **.
    settings: dict[str, Any] = {"max_tokens": _ANTHROPIC_MAX_TOKENS}
    if not thinking.enabled:
        return cast(ModelSettings, settings)

    if spec.reasoning_type is ReasoningType.ANTHROPIC_ADAPTIVE:
        settings["anthropic_thinking"] = {"type": "adaptive"}
        settings["extra_body"] = {"output_config": {"effort": thinking.effort.value}}
    elif spec.reasoning_type is ReasoningType.ANTHROPIC_BUDGET:
        settings["anthropic_thinking"] = {
            "type": "enabled",
            "budget_tokens": _clamp_thinking_budget(thinking.budget),
        }
    return cast(ModelSettings, settings)


def _clamp_thinking_budget(budget: int) -> int:
    """Clamp a requested budget into Anthropic's valid ``budget_tokens`` window."""
    return max(
        _MIN_ANTHROPIC_THINKING_BUDGET,
        min(budget, _MAX_ANTHROPIC_THINKING_BUDGET),
    )
